<script setup lang="ts">
import {computed, ref} from 'vue'; import LeadConversionForm from '../../components/crm/LeadConversionForm.vue'; import CrmEntityForm from '../../components/crm/CrmEntityForm.vue'; import BiddingForm from '../../components/crm/BiddingForm.vue'; import PaymentStagesField from '../../components/crm/PaymentStagesField.vue'; import DetailDrawer from '../../components/common/DetailDrawer.vue'; import DetailFields from '../../components/common/DetailFields.vue'; import {useQuery} from '@tanstack/vue-query'; import {crmRepository} from '../../services/crmRepository';
const props=defineProps<{kind:'leads'|'opportunities'|'followUps'|'contracts'}>(); const biddingOpen=ref(false); const editorOpen=ref(false); const conversionOpen=ref(false); const saving=ref(false); const saveError=ref(''); const actionMessage=ref(''); const selected=ref<Record<string,unknown>|null>(null); const transitionSaving=ref(false); const transitionError=ref(''); const detail=ref<Record<string,unknown>|null>(null); const paymentStages=ref<Array<Record<string,unknown>>>([]); const detailLoading=ref(false); const detailError=ref(''); const config={leads:{title:'线索管理',kicker:'CRM LEADS',query:crmRepository.leads,columns:['线索名称','客户','负责人','状态','创建时间']},opportunities:{title:'商机管理',kicker:'CRM OPPORTUNITIES',query:crmRepository.opportunities,columns:['商机名称','客户','阶段','金额','预计成交']},followUps:{title:'跟进记录',kicker:'CRM FOLLOW UPS',query:crmRepository.followUps,columns:['跟进主题','客户','方式','负责人','跟进时间']},contracts:{title:'合同管理',kicker:'CRM CONTRACTS',query:crmRepository.contracts,columns:['合同名称','客户','合同金额','付款阶段','签署时间']}} as const; const current=computed(()=>config[props.kind]); const keyword=ref(''); const query=useQuery({queryKey:computed(()=>['crm',props.kind]),queryFn:()=>current.value.query({page:1,pageSize:100})}); const refresh=()=>{void query.refetch()}; const edit=()=>{editorOpen.value=true;saveError.value=''}; const saveConversion=async(value:Record<string,unknown>)=>{saving.value=true;saveError.value='';try{const result=await crmRepository.convertLead(String(selected.value?.id),value);conversionOpen.value=false;actionMessage.value='已成功转为商机';selected.value=null;await query.refetch(); if(result?.id) window.setTimeout(()=>{window.location.hash=`/app/crm_opportunities?opportunityId=${result.id}`},0)}catch(e){saveError.value=e instanceof Error?e.message:'转换失败'}finally{saving.value=false}}; const saveBidding=async(value:Record<string,unknown>)=>{try{await crmRepository.updateBidding(String(selected.value?.id),value);biddingOpen.value=false;detail.value=await crmRepository.opportunity(String(selected.value?.id))}catch(e){saveError.value=e instanceof Error?e.message:'投标更新失败'}}; const transition=async(to:string)=>{if(!selected.value?.id)return;transitionSaving.value=true;transitionError.value='';try{await crmRepository.transitionOpportunity(String(selected.value.id),{stage:to});detail.value=await crmRepository.opportunity(String(selected.value.id));await query.refetch()}catch(e){transitionError.value=e instanceof Error?e.message:'阶段流转失败'}finally{transitionSaving.value=false}}; const saveEntity=async(value:Record<string,unknown>)=>{saving.value=true;saveError.value='';try{if(props.kind==='leads')await crmRepository.updateLead(String(selected.value?.id),value);else if(props.kind==='opportunities')await crmRepository.updateOpportunity(String(selected.value?.id),value);else if(props.kind==='followUps')await crmRepository.createFollowUp(value);else if(props.kind==='contracts'){const body={...value,paymentStages:paymentStages.value};if(selected.value?.id)await crmRepository.updateContract(String(selected.value.id),body);else await crmRepository.createContract(body);}editorOpen.value=false;await query.refetch()}catch(e){saveError.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}; const openDetail=async(item:Record<string,unknown>)=>{selected.value=item;detail.value=null;detailLoading.value=true;try{const loader=props.kind==='leads'?crmRepository.lead:props.kind==='opportunities'?crmRepository.opportunity:props.kind==='followUps'?crmRepository.followUp:crmRepository.contract;detail.value=await loader(String(item.id));paymentStages.value=Array.isArray(detail.value.paymentStages)?detail.value.paymentStages:[]}catch(e){detailError.value=e instanceof Error?e.message:'详情加载失败'}finally{detailLoading.value=false}}; const rows=computed(()=>{const items=query.data.value?.items||[]; const key=keyword.value.trim().toLowerCase(); return key?items.filter(item=>Object.values(item).some(value=>String(value??'').toLowerCase().includes(key))):items}); const cell=(item:Record<string,unknown>,index:number)=>{const keys=props.kind==='leads'?['name','customerName','ownerName','status','createdAt']:props.kind==='opportunities'?['name','customerName','stage','amount','expectedCloseDate']:props.kind==='followUps'?['title','customerName','method','ownerName','date']:['name','customerName','amount','paymentStage','signDate']; return item[keys[index]]??'—'};
</script>
<template><section class="crm-view"><div class="section-heading"><div><span class="eyebrow">{{current.kicker}}</span><h2>{{current.title}}</h2></div><button class="secondary" @click="refresh">刷新</button></div><p v-if="actionMessage" class="form-feedback">{{actionMessage}}</p><div class="toolbar"><input v-model="keyword" :placeholder="`搜索${current.title}`"/><span>{{rows.length}} 条记录</span></div><div v-if="query.isPending" class="state">正在加载{{current.title}}…</div><div v-else-if="query.isError" class="state error">{{current.title}}加载失败。</div><div v-else-if="!rows.length" class="state">暂无匹配记录。</div><div v-else class="table-wrap"><table><thead><tr><th v-for="column in current.columns" :key="column">{{column}}</th></tr></thead><tbody><tr v-for="item in rows" :key="String(item.id)" @click="openDetail(item)"><td v-for="(_, index) in current.columns" :key="index">{{cell(item,index)}}</td></tr></tbody></table></div><DetailDrawer :open="Boolean(selected)" :title="`${current.title}详情`" @close="selected=null"><p v-if="detailLoading" class="state">正在加载详情…</p><p v-else-if="detailError" class="state error">{{detailError}}</p><p v-if="saving" class="form-feedback">正在保存…</p><p v-if="saveError" class="form-feedback error">{{saveError}}</p><DetailFields v-else-if="detail" :record="detail" :fields="[{key:'name',label:'名称'},{key:'title',label:'主题'},{key:'customerName',label:'客户'},{key:'ownerName',label:'负责人'},{key:'status',label:'状态'},{key:'stage',label:'阶段'},{key:'amount',label:'金额'},{key:'description',label:'描述'}]"/><div v-if="kind==='opportunities'" class="form-actions"><button class="secondary" :disabled="transitionSaving" @click="transition('跟进中')">转为跟进中</button><button class="secondary" :disabled="transitionSaving" @click="transition('赢单')">标记赢单</button></div><p v-if="transitionError" class="form-feedback error">{{transitionError}}</p><button v-if="kind==='leads'" class="primary" @click="conversionOpen=true">转为商机</button><button v-if="kind==='opportunities' && detail?.stage==='招投标'" class="secondary" @click="biddingOpen=true">编辑投标</button></DetailDrawer><DetailDrawer :open="editorOpen" :title="`编辑${current.title}`" @close="editorOpen=false"><PaymentStagesField v-if="kind==='contracts'" v-model="paymentStages"/><CrmEntityForm :model-value="detail" :fields="[{key:'name',label:'名称'},{key:'title',label:'主题'},{key:'status',label:'状态'},{key:'stage',label:'阶段'},{key:'amount',label:'金额',type:'number'},{key:'description',label:'描述',type:'textarea'}]" @save="saveEntity" @cancel="editorOpen=false"/></DetailDrawer><DetailDrawer :open="conversionOpen" title="线索转商机" @close="conversionOpen=false"><LeadConversionForm :source="detail" @save="saveConversion" @cancel="conversionOpen=false"/></DetailDrawer><DetailDrawer :open="biddingOpen" title="投标信息" @close="biddingOpen=false"><BiddingForm :model-value="detail" @save="saveBidding" @cancel="biddingOpen=false"/></DetailDrawer><DetailDrawer :open="conversionOpen" title="线索转商机" @close="conversionOpen=false"><LeadConversionForm :source="detail" @save="saveConversion" @cancel="conversionOpen=false"/></DetailDrawer></section></template>
